```c
#include <stdio.h>


// Fibbonaccin lukujono kohdalla n ( F(n) ) lasketaan seuraavasti
// F(n) = F(n-1) + F(n-2)
// Lukujonolla on kuitenkin kaksi ennalta määriteltyä pistettä, 0 ja 1.
// F(1) = 1
// F(0) = 0
int fib(unsigned int n){

    if(n <= 1)
        return n;

    return fib(n-1) + fib(n-2);

}

int main(){

    // Toisto yhdestä kymmeneen
    for(int i = 1; i<=10; i++){

        // Tulosta F(n)
        printf("%i",fib(i));

    }

    return 0;

}
```

